def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_defects = 0
    my_defects = 0
    for a, b in history:
        if b == 'D':
            opp_defects += 1
        if a == 'D':
            my_defects += 1

    if opp_defects == 0:
        if my_defects == 0:
            if n >= 5:
                return 'D'
            return 'C'
        else:
            return 'D'

    if opp_defects > n * 0.5:
        return 'D'

    last_my, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    else:
        recent_my_def = False
        if last_my == 'D':
            recent_my_def = True
        elif n >= 2 and history[-2][0] == 'D':
            recent_my_def = True

        if recent_my_def:
            return 'C'
        else:
            return 'D'
